inline vec2i operator-(vec2i a) { return vec2i(-a.x, -a.y); }
inline vec2i abs(vec2i a) { return vec2i(abs(a.x), abs(a.y)); }
inline vec2i min(vec2i a, vec2i b) { return vec2i(min(a.x, b.x), min(a.y, b.y)); }
inline vec2i max(vec2i a, vec2i b) { return vec2i(max(a.x, b.x), max(a.y, b.y)); }
inline vec2i clamp(vec2i x, vec2i lo, vec2i hi) { return min(max(x, lo), hi); }
inline vec3f cross(vec3f a, vec3f b) { return vec3f(a.y * b.z - a.z * b.y, a.z * b.x - a.x * b.z, a.x * b.y - a.y * b.x); }
